package az.youtube.dto.event;

import java.time.Instant;
import java.util.UUID;

/**
 * A view the player reported after the minimum watch time.
 *
 * @param eventId generated by the player once per view; a retried request repeats it, so it is counted once
 */
public record ViewEvent(UUID eventId, long videoId, long userId, Instant occurredAt) {
}
